// app/api/leads/route.ts
import { NextResponse } from 'next/server';
export async function POST(req: Request) {
  const body = await req.json();
  if (!body.email) {
    return NextResponse.json({ error: 'Email is required' }, { status: 400 });
  }
  return NextResponse.json({ success: true, lead: { id: '1', email: body.email } }, { status: 201 });
}

'use client';
import { useState } from 'react';
// Modal state handler toggles modal visibility and handles form submit
export function LeadModal({ isOpen, onClose }: { isOpen: boolean; onClose: () => void }) {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 bg-slate-900/40 flex items-center justify-center p-4 z-50">
      <div className="bg-white rounded-2xl p-6 w-full max-w-md shadow-2xl">
        <h2 className="text-lg font-bold text-heading mb-4">Get started with Nimbus</h2>
        <input className="w-full border rounded-lg p-2.5 text-sm mb-4" placeholder="Work email" />
        <button onClick={onClose} className="w-full bg-primary text-white py-2.5 rounded-lg text-sm font-semibold">Continue</button>
      </div>
    </div>
  );
}
